package com.resolveAi.resolveai_backend.invoice.entity;import com.resolveAi.resolveai_backend.common.entity.BaseEntity;import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;@Entity@Table(name = "invoice_items")@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builderpublic class InvoiceItem extends BaseEntity {    @ManyToOne(fetch = FetchType.LAZY)    @JoinColumn(name = "invoice_id", nullable = false)    private Invoice invoice;    private String productName;    private Integer quantity;    @Column(precision = 15, scale = 2)    private BigDecimal unitPrice;    @Column(precision = 15, scale = 2)    private BigDecimal totalPrice;}